INSERT INTO ai_call_agent_status VALUES(108, 2, '孙律师', '1', '2026-03-14 08:50:00', null, '192.168.1.16', 'admin', '2026-03-14 08:50:00', '', null, '交通事故坐席');
INSERT INTO ai_call_agent_status VALUES(109, 2, '周律师', '0', null, null, '192.168.1.17', 'admin', '2026-03-14 10:00:00', '', null, '离线');
INSERT INTO ai_call_record VALUES(1000, '13800138001', '张先生', '北京市朝阳区建国路88号', '2026-03-14 09:05:00', '2026-03-14 09:12:30', 450, 102, 1, '我想咨询劳动合同解除的赔偿问题，公司单方面解除合同，我工作5年了，能获得多少赔偿？', '根据劳动合同法第47条，公司单方面解除劳动合同，您可获得5个月工资的经济补偿金。如果是违法解除，可主张双倍赔偿。建议您收集劳动合同、工资流水等证据，先与公司协商，协商不成可申请劳动仲裁。', '1', null, null, 'admin', '2026-03-14 09:05:00', '', null, '劳动纠纷咨询');
INSERT INTO ai_call_record VALUES(1001, '13900139002', '李女士', '广州市天河区体育西路50号', '2026-03-14 09:15:00', '2026-03-14 09:28:00', 780, 103, 2, '我想咨询离婚财产分割的问题，结婚10年，有两套房产和一个孩子，想争取抚养权和房产', '根据民法典相关规定，婚后购买的房产属于夫妻共同财产，一般平均分割。关于孩子抚养权，法院会根据有利于孩子成长的原则判决。建议您准备收入证明、住房证明等材料，有利于争取抚养权。', '1', null, null, 'admin', '2026-03-14 09:15:00', '', null, '婚姻家庭咨询');
INSERT INTO ai_call_record VALUES(1002, '15000150003', '王先生', '上海市浦东新区陆家嘴环路100号', '2026-03-14 09:30:00', '2026-03-14 09:38:00', 480, 104, 3, '我父亲被车撞了，对方全责，现在住院治疗，想问赔偿标准是什么？', '交通事故人身损害赔偿包括：医疗费、护理费、误工费、住院伙食补助费、营养费等，如果构成伤残还可主张残疾赔偿金。建议先做伤残鉴定，保留好所有医疗票据。', '1', null, null, 'admin', '2026-03-14 09:30:00', '', null, '交通事故咨询');
INSERT INTO ai_call_record VALUES(1003, '13600136004', '赵女士', '深圳市南山区科技园路8号', '2026-03-14 09:45:00', '2026-03-14 09:52:00', 420, 102, 4, '我在网上买了一台电脑，收到货发现有质量问题，商家拒绝退换，我该怎么维权？', '根据消费者权益保护法，商品存在质量问题，您有权要求退货、换货或修理。建议先与商家协商，协商不成可向12315投诉，也可通过电商平台维权通道处理。保留好购物凭证和沟通记录。', '1', null, null, 'admin', '2026-03-14 09:45:00', '', null, '消费者维权咨询');
INSERT INTO ai_call_record VALUES(1004, '18700187005', '钱先生', '成都市武侯区人民南路四段1号', '2026-03-14 10:00:00', '2026-03-14 10:15:00', 900, 105, 5, '我想咨询商标侵权的问题，我们公司的注册商标被另一家公司使用了，怎么维权？', '商标侵权可以通过以下途径维权：1.发律师函警告对方停止侵权；2.向市场监督管理局投诉；3.向法院起诉主张赔偿。建议先公证保全侵权证据，计算侵权造成的损失或对方获利情况。', '1', null, null, 'admin', '2026-03-14 10:00:00', '', null, '知识产权咨询');
INSERT INTO ai_call_record VALUES(1005, '15800158006', '孙女士', '杭州市西湖区文三路90号', '2026-03-14 10:20:00', '2026-03-14 10:26:00', 360, 103, 2, '我想起诉离婚，但对方不同意，请问怎么办？需要准备什么材料？', '对方不同意离婚的情况下，您可以直接向法院起诉。需要准备：民事起诉状、结婚证、身份证、感情破裂的证据（如分居证明、家暴记录等）。法院会先调解，调解不成再判决。', '1', null, null, 'admin', '2026-03-14 10:20:00', '', null, '婚姻家庭咨询');
INSERT INTO ai_call_record VALUES(1006, '13700137007', '周先生', '南京市鼓楼区中山路100号', '2026-03-14 10:35:00', '2026-03-14 10:42:00', 420, 102, 1, '我在工地上班受伤了，老板说只给医药费，我想问工伤赔偿标准是什么？', '工伤赔偿包括：医疗费、停工留薪期工资、护理费、一次性伤残补助金等。建议您先申请工伤认定（1年内），再做劳动能力鉴定，根据伤残等级计算赔偿金额。如果老板不配合，可向人社局投诉。', '1', null, null, 'admin', '2026-03-14 10:35:00', '', null, '工伤赔偿咨询');
INSERT INTO ai_call_record VALUES(1007, '15900159008', '吴女士', '武汉市江汉区解放大道688号', '2026-03-14 10:50:00', '2026-03-14 11:05:00', 900, 104, 3, '我骑电动车被小车撞了，交警认定对方主责，但对方保险公司赔得太少，我想起诉', '对方主责的情况下，保险公司赔偿不足部分可向肇事者主张。起诉需要准备：事故认定书、医疗票据、伤残鉴定报告、误工证明等。建议先计算总损失，再扣除保险已赔部分，剩余向法院主张。', '1', null, null, 'admin', '2026-03-14 10:50:00', '', null, '交通事故咨询');
INSERT INTO ai_call_record VALUES(1008, '18600186009', '郑先生', '重庆市渝中区解放碑步行街', '2026-03-14 11:10:00', '2026-03-14 11:18:00', 480, 105, 6, '我朋友因涉嫌盗窃被拘留了，家属可以做什么？能见人吗？', '刑事拘留期间家属不能会见，但可以委托律师会见。建议尽快委托律师介入，律师可以会见嫌疑人、了解案情、提供法律帮助、申请取保候审等。在侦查阶段律师的帮助非常重要。', '1', null, null, 'admin', '2026-03-14 11:10:00', '', null, '刑事辩护咨询');
INSERT INTO ai_call_record VALUES(1009, '13500135010', '冯女士', '西安市碑林区南大街36号', '2026-03-14 11:25:00', '2026-03-14 11:30:00', 300, 102, 7, '房东不退押金，说房子有损坏，但我们搬走时拍了照是完好的，怎么办？', '如果您有退房时的照片证明房屋完好，房东无权扣留押金。建议：1.先与房东协商，出示照片证据；2.协商不成可向住建部门投诉；3.也可向法院起诉要求退还押金。保留好租赁合同和照片。', '1', null, null, 'admin', '2026-03-14 11:25:00', '', null, '房屋租赁纠纷');
INSERT INTO ai_call_record VALUES(1010, '18800188011', '陈先生', '天津市和平区南京路189号', '2026-03-14 13:00:00', '2026-03-14 13:12:00', 720, 103, 2, '我和前妻的离婚协议上写的是孩子归她，但现在她不要孩子了，我该怎么办？', '对方不履行抚养义务的情况下，您可以向法院起诉变更抚养权。需要准备：离婚协议、对方不履行抚养义务的证据、您有抚养能力的证明。法院会以有利于孩子为原则判决。', '1', null, null, 'admin', '2026-03-14 13:00:00', '', null, '婚姻家庭咨询');
INSERT INTO ai_call_record VALUES(1011, '15700157012', '褚女士', '苏州市姑苏区人民路500号', '2026-03-14 13:20:00', '2026-03-14 13:28:00', 480, 104, 8, '我在美容院做了个项目出了问题，脸部有损伤，他们只同意退项目费，我要求赔偿', '美容事故属于医疗损害或消费者权益纠纷。您可以主张：退还项目费、医疗费、误工费、精神损害抚慰金等。建议先到正规医院就诊并保留诊断证明，与美容院协商，协商不成可向卫生监督部门投诉或起诉。', '1', null, null, 'admin', '2026-03-14 13:20:00', '', null, '消费者维权咨询');
INSERT INTO ai_call_record VALUES(1012, '13800138013', '卫先生', '长沙市岳麓区麓山南路1号', '2026-03-14 13:40:00', '2026-03-14 13:47:00', 420, 102, 1, '公司拖欠工资3个月了，催了好多次都不给，我可以直接离职并要求赔偿吗？', '根据劳动合同法第38条，公司未及时足额支付劳动报酬的，您可以单方解除合同并要求经济补偿。建议：1.发书面催告函；2.向劳动监察大队投诉；3.申请劳动仲裁主张欠薪和经济补偿。', '1', null, null, 'admin', '2026-03-14 13:40:00', '', null, '劳动纠纷咨询');
INSERT INTO ai_call_record VALUES(1013, '13900139014', '蒋女士', '郑州市金水区花园路100号', '2026-03-14 14:00:00', '2026-03-14 14:10:00', 600, 103, 2, '老公出轨了，我想离婚，但他把财产都转移到他父母名下了，我能追回吗？', '婚内转移夫妻共同财产的行为可以追回。根据民法典，您可以：1.申请法院调查对方银行流水和房产过户记录；2.主张转移的财产仍然属于夫妻共同财产；3.对方恶意转移财产的，可以少分或不分。建议尽快起诉并申请财产保全。', '1', null, null, 'admin', '2026-03-14 14:00:00', '', null, '婚姻家庭咨询');
INSERT INTO ai_call_record VALUES(1014, '15000150015', '沈先生', '合肥市蜀山区长江西路200号', '2026-03-14 14:20:00', '2026-03-14 14:28:00', 480, 102, 9, '我买了期房，开发商延期交房8个月了，我可以要求退房吗？赔偿怎么算？', '开发商延期交房，您可以选择：1.继续履行合同，主张延期交房的违约金（按合同约定或同地段租金标准）；2.如果延期超过合理期限，可以主张解除合同并要求退款及赔偿。建议先查看购房合同中的交房及违约条款。', '1', null, null, 'admin', '2026-03-14 14:20:00', '', null, '房产纠纷咨询');
INSERT INTO ai_call_record VALUES(1015, '13600136016', '韩女士', '福州市鼓楼区五四路89号', '2026-03-14 14:35:00', '2026-03-14 14:37:00', 120, 105, 10, '我想咨询一下遗嘱怎么写才有效？', '遗嘱的有效要件：1.遗嘱人具有完全民事行为能力；2.遗嘱是真实意思表示；3.形式合法。建议采用公证遗嘱或律师见证遗嘱，效力最强。自书遗嘱需亲笔书写、签名、注明年月日。代书遗嘱需两个以上见证人。', '1', null, null, 'admin', '2026-03-14 14:35:00', '', null, '遗嘱继承咨询');
INSERT INTO ai_call_record VALUES(1016, '18700187017', '杨先生', '昆明市盘龙区北京路600号', '2026-03-14 14:50:00', '2026-03-14 14:55:00', 300, 104, 3, '我开车撞了闯红灯的行人，交警判我次责，这个合理吗？我需要赔偿多少？', '机动车与行人事故中，即使行人违规，机动车一方通常仍需承担一定责任（一般不超过10%的赔偿责任）。赔偿由交强险先赔，不足部分按责任比例由商业险赔付。次责一般承担30%-40%的赔偿责任。', '1', null, null, 'admin', '2026-03-14 14:50:00', '', null, '交通事故咨询');
INSERT INTO ai_call_record VALUES(1017, '15800158018', '朱女士', '厦门市思明区中山路120号', '2026-03-14 15:10:00', '2026-03-14 15:25:00', 900, 103, 2, '家暴离婚，有报警记录和伤情鉴定，能一次判离吗？孩子抚养权和房产怎么分？', '有家暴证据的情况下，法院调解无效应当判决离婚。家暴方在财产分割上可以少分。孩子抚养权一般判给非施暴方。建议您申请人身安全保护令，起诉离婚时一并主张损害赔偿。', '1', null, null, 'admin', '2026-03-14 15:10:00', '', null, '婚姻家庭咨询');
INSERT INTO ai_call_record VALUES(1018, '13700137019', '秦先生', '无锡市梁溪区人民中路150号', '2026-03-14 15:30:00', '2026-03-14 15:32:00', 120, 102, 1, '被公司裁员了，公司只给N的赔偿，我能争取2N吗？', '合法裁员经济补偿为N（工作年限×月工资）。如果公司违法解除劳动合同，您可以主张2N的赔偿金。关键看裁员程序是否合法：是否提前30天通知、是否向工会说明、是否向人社局报告。如果程序违法，可以主张2N。', '1', null, null, 'admin', '2026-03-14 15:30:00', '', null, '劳动纠纷咨询');
INSERT INTO ai_call_record VALUES(1019, '15900159020', '许女士', '济南市历下区泉城路180号', '2026-03-14 15:45:00', '2026-03-14 15:48:00', 180, 105, 11, '被人借钱不还，有借条，怎么起诉？', '有借条的情况下，可以直接向被告住所地或借款履行地法院起诉。需要准备：起诉状、借条原件、转账记录、身份信息。注意诉讼时效3年，从还款期限届满之日起算。建议先发律师函催收，不行再起诉。', '1', null, null, 'admin', '2026-03-14 15:45:00', '', null, '民间借贷咨询');
INSERT INTO ai_call_record VALUES(1020, '18600186021', '何先生', '广州市越秀区东风中路', '2026-03-14 16:00:00', null, 0, 102, 1, null, null, '3', null, null, 'admin', '2026-03-14 16:00:00', '', null, '未接来电');
INSERT INTO ai_call_record VALUES(1021, '13500135022', '吕女士', '东莞市南城区莞太路', '2026-03-14 16:15:00', '2026-03-14 16:30:00', 900, 103, 2, '我要咨询劳动仲裁的流程，公司没签劳动合同也没交社保', '未签劳动合同可主张双倍工资（最多11个月），未交社保可要求补缴。劳动仲裁流程：1.准备仲裁申请书和证据；2.向劳动仲裁委提交；3.等待受理和开庭；4.仲裁裁决。建议收集工资记录、工牌等证明劳动关系的证据。', '2', 100, null, 'admin', '2026-03-14 16:15:00', '', null, '转接-劳动纠纷');
INSERT INTO ai_call_record VALUES(1022, '18800188023', '施先生', '佛山市禅城区祖庙路', '2026-03-14 16:35:00', null, 0, 102, 1, '咨询房屋拆迁补偿标准', null, '0', null, null, 'admin', '2026-03-14 16:35:00', '', null, '正在通话中');
INSERT INTO ai_call_ticket VALUES(10000, 'TKT20260314090000AB12CD', 1000, '劳动合同解除赔偿咨询', '来电人张先生咨询公司单方面解除劳动合同的赔偿问题，工作5年，要求经济补偿金', '2', '2', 103, '李律师', '已解答：根据劳动合同法第47条，可获得5个月工资的经济补偿，建议收集证据协商或申请劳动仲裁', '2026-03-14 09:15:00', null, 'admin', '2026-03-14 09:05:00', 'admin', '2026-03-14 09:15:00', '劳动纠纷');
INSERT INTO ai_call_ticket VALUES(10001, 'TKT20260314091500AB34EF', 1001, '离婚财产分割与抚养权', '来电人李女士咨询离婚财产分割问题，结婚10年，两套房产，争取孩子抚养权', '1', '1', 104, '王律师', null, null, null, 'admin', '2026-03-14 09:15:00', '', null, '婚姻家庭');
INSERT INTO ai_call_ticket VALUES(10002, 'TKT20260314093000AB56GH', 1002, '交通事故人身损害赔偿', '来电人王先生父亲被车撞伤，对方全责，咨询赔偿标准', '2', '2', 104, '王律师', '已解答：赔偿包括医疗费、护理费、误工费、伤残赔偿金等，建议先做伤残鉴定', '2026-03-14 09:40:00', null, 'admin', '2026-03-14 09:30:00', 'admin', '2026-03-14 09:40:00', '交通事故');
INSERT INTO ai_call_ticket VALUES(10003, 'TKT20260314094500AB78IJ', 1003, '网购电脑质量问题维权', '来电人赵女士购买电脑存在质量问题，商家拒绝退换', '3', '2', 102, '张律师', '已解答：可要求退货换货，协商不成可向12315投诉', '2026-03-14 10:00:00', null, 'admin', '2026-03-14 09:45:00', 'admin', '2026-03-14 10:00:00', '消费者维权');
INSERT INTO ai_call_ticket VALUES(10004, 'TKT20260314100000AB90KL', 1004, '商标侵权维权咨询', '来电人钱先生公司注册商标被侵权，咨询维权途径', '2', '2', 105, '赵律师', '已解答：可发律师函、向市监局投诉或起诉，建议先公证保全证据', '2026-03-14 10:20:00', null, 'admin', '2026-03-14 10:00:00', 'admin', '2026-03-14 10:20:00', '知识产权');
INSERT INTO ai_call_ticket VALUES(10005, 'TKT20260314102000ABC1MN', 1005, '起诉离婚流程咨询', '来电人孙女士想起诉离婚但对方不同意，咨询起诉流程和材料', '